import React from 'react';
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from 'remotion';

const D = 180, FPS = 30;

// Deterministic fence path across the safe zone (x 140..1780), gentle sine undulation
const X0 = 140, X1 = 1780, BASE_Y = 500;
const wave = (x: number) =>
  BASE_Y + Math.sin((x - X0) / 210) * 26 + Math.cos((x - X0) / 90) * 8;

const POINTS: Array<[number, number]> = [];
for (let x = X0; x <= X1; x += 8) {
  POINTS.push([x, wave(x)]);
}

// approximate total path length (deterministic sampling)
let PATH_LEN = 0;
for (let i = 1; i < POINTS.length; i++) {
  const dx = POINTS[i][0] - POINTS[i - 1][0];
  const dy = POINTS[i][1] - POINTS[i - 1][1];
  PATH_LEN += Math.sqrt(dx * dx + dy * dy);
}

// visible distance fraction mapped from drawn length (line completes at frame 130)
const totalKm = 5614;

export default function MotionScene({ scene, context }: { scene: any; context: any }) {
  const frame = useCurrentFrame();
  const f = Math.min(frame, D - 1);

  // wire drawing progress
  const draw = interpolate(f, [2, 130], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });

  // km counter tied to drawn progress, eased but continuing to tick
  const kmShown = Math.round(draw * totalKm);
  const kmDone = f >= 130;

  // post pop timing
  const postSpring = (i: number) =>
    spring({
      frame: f - 4 - i * 5,
      fps: FPS,
      config: { damping: 12, stiffness: 140, mass: 0.5 },
    });

  // zone tint reveal as the line splits the two halves
  const zoneIn = interpolate(f, [40, 90], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  // shimmer pulse on the finished wire (dashed overlay drifting right)
  const shimmerPhase = kmDone ? (f - 130) * 14 : 0;
  const wirePulse = kmDone
    ? Math.max(0, Math.sin((f - 130) * 0.28)) * 0.5
    : 0;

  // comparison benchmark
  const bench = spring({
    frame: f - 140,
    fps: FPS,
    config: { damping: 14, stiffness: 120 },
  });

  // die pulsing slightly toward the cut
  const endPulse = interpolate(f, [172, 180], [1, 1.012], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });

  const polyline = POINTS.map((p) => `${p[0]},${p[1]}`).join(' ');

  // posts along the drawn path only
  const postCount = 44;
  const posts: JSX.Element[] = [];
  for (let i = 0; i < postCount; i++) {
    const t = i / (postCount - 1);
    const px = X0 + t * (X1 - X0);
    const py = wave(px);
    // only show posts whose position along the path has been reached
    const reached = draw > t * 0.99;
    const s = reached ? postSpring(i) : 0;
    if (s <= 0.001) continue;
    const h = 78 * s;
    posts.push(
      <g key={i} transform={`translate(${px},${py})`} opacity={Math.min(1, s + 0.2)}>
        <rect x={-2.5} y={-h} width={5} height={h} fill="#4a3b2a" rx={2} />
        <rect x={-4.5} y={-h} width={9} height={7} fill="#6b573c" rx={2} />
      </g>
    );
  }

  return (
    <AbsoluteFill style={{ transform: `scale(${endPulse})`, transformOrigin: 'center center' }}>
      {/* banded ground: arid north above the line, fertile south below */}
      <div
        style={{
          position: 'absolute', inset: 0,
          background: 'linear-gradient(180deg, #c98b4b 0%, #d9a05e 30%, #e3b87e 48%, #d8d2a8 53%, #a8b784 70%, #7fa15e 100%)',
          opacity: 0.9,
        }}
      />
      {/* zone labels appear as tints settle */}
      <div
        style={{
          position: 'absolute', top: 200, left: '50%', transform: `translate(-50%, ${(1 - zoneIn) * -20}px)`,
          opacity: zoneIn * 0.75,
          fontFamily: 'Helvetica, Arial, sans-serif', fontWeight: 700, fontSize: 34,
          letterSpacing: 10, color: '#5a3c22',
        }}
      >
        ARID INTERIOR
      </div>

      <svg
        width="1920"
        height="1080"
        viewBox="0 0 1920 1080"
        style={{ position: 'absolute', inset: 0 }}
      >
        {/* fertile south wash, revealed under the finished line */}
        <rect
          x={0}
          y={BASE_Y + 60}
          width={X0 + (X1 - X0) * draw}
          height={700}
          fill="rgba(90,140,80,0.18)"
          opacity={zoneIn}
        />
        {posts}
        {/* main wire */}
        <polyline
          points={polyline}
          fill="none"
          stroke="#2b2b2b"
          strokeWidth={4}
          strokeDasharray={PATH_LEN}
          strokeDashoffset={PATH_LEN * (1 - draw)}
          strokeLinecap="round"
        />
        {/* dashed wire strands overlay */}
        <polyline
          points={polyline}
          fill="none"
          stroke="rgba(255,255,255,0.65)"
          strokeWidth={2}
          strokeDasharray="10 18"
          strokeDashoffset={-shimmerPhase}
          opacity={0.35 + wirePulse * 0.4}
        />
        {/* arrowhead at revealed tip */}
        {draw > 0.005 && draw < 0.999 && (() => {
          const idx = Math.min(POINTS.length - 1, Math.round(draw * (POINTS.length - 1)));
          const [tx, ty] = POINTS[idx];
          return (
            <g transform={`translate(${tx},${ty})`} opacity={0.9}>
              <polygon points="0,-10 18,0 0,10" fill="#1c1c1c" />
            </g>
          );
        })()}
      </svg>

      {/* km counter, bottom-left in safe zone */}
      <div
        style={{
          position: 'absolute', left: 80, bottom: 130,
          fontFamily: 'Helvetica, Arial, sans-serif',
          opacity: interpolate(f, [1, 8], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }),
        }}
      >
        <div
          style={{
            fontWeight: 800,
            fontSize: 96,
            fontVariantNumeric: 'tabular-nums',
            color: '#2a2622',
            textShadow: '0 2px 4px rgba(0,0,0,0.25)',
            letterSpacing: -2,
          }}
        >
          {kmShown.toLocaleString('en-US')} km
        </div>
        <div
          style={{
            fontSize: 26, fontWeight: 300, letterSpacing: 6, color: '#3d3327',
            marginTop: 4,
          }}
        >
          CONTINUOUS WIRE BARRIER
        </div>
      </div>

      {/* Great Wall comparison tick, right side within safe zone */}
      <div
        style={{
          position: 'absolute', right: 80, bottom: 150,
          maxWidth: 520, boxSizing: 'border-box',
          transform: `translateX(${interpolate(bench, [0, 1], [40, 0])}px)`,
          opacity: bench,
        }}
      >
        <div
          style={{
            display: 'flex', alignItems: 'center', gap: 14,
          }}
        >
          <div
            style={{
              width: 6, height: 64, background: '#2a2622', borderRadius: 3,
            }}
          />
          <div
            style={{
              fontFamily: 'Helvetica, Arial, sans-serif',
              fontWeight: 700, fontSize: 34, color: '#2a2622',
              textShadow: '0 2px 4px rgba(0,0,0,0.25)',
              lineHeight: 1.2,
            }}
          >
            Longer than
            <br />
            the Great Wall
          </div>
        </div>
      </div>

      {/* FERTILE SOUTH pill below the line, shifts with the split */}
      <div
        style={{
          position: 'absolute', left: '50%', top: BASE_Y + 130,
          transform: `translate(-50%, ${(1 - zoneIn) * 24}px)`,
          opacity: zoneIn,
        }}
      >
        <div
          style={{
            background: 'rgba(52,84,44,0.85)',
            color: '#f2efe4',
            fontFamily: 'Helvetica, Arial, sans-serif',
            fontWeight: 700, fontSize: 32, letterSpacing: 8,
            padding: '14px 36px',
            borderRadius: 999,
            border: '2px solid rgba(255,255,255,0.35)',
          }}
        >
          FERTILE SOUTH
        </div>
      </div>
    </AbsoluteFill>
  );
}
